import { globSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { createGenerator } from 'unocss'
import config from '../../../ui/uno.config'

// After bunup: the utilities the kit's components use, generated by modo-ui's
// own UnoCSS config from dist/, for a host on modo-ui's prebuilt styles.css.
// No preflights or tokens: those come from modo-ui's stylesheet, loaded first.

const ROOT = join(import.meta.dirname, '..')
const code = globSync('dist/**/*.js', { cwd: ROOT })
  .sort()
  .map(file => readFileSync(join(ROOT, file), 'utf8'))
  .join('\n')

const uno = await createGenerator(config)
const { css } = await uno.generate(code, { preflights: false })
writeFileSync(
  join(ROOT, 'dist', 'styles.css'),
  `/* @justanarthur/modo-ui-notch: load after @justanarthur/modo-ui/styles.css. */\n${css}`,
)
